  }
}

function areCookiesEnabled() {
  // 1. Always trust React Native app / WebView environments where cookies are managed natively
  if (window.isApp || (typeof window.ReactNativeWebView !== 'undefined')) {
    return true;
  }
  try {
    // 2. If navigator explicitly states cookies are disabled, return false
    if (navigator.cookieEnabled === false) {
      return false;
    }
    // 3. Test setting a cookie with path=/ and SameSite=Lax (avoids SameSite=Strict rejections in embedded contexts/Android WebViews)
    document.cookie = "cookieEnabled=1; path=/; SameSite=Lax";
    const cookiesEnabled = document.cookie.indexOf("cookieEnabled=") !== -1 || navigator.cookieEnabled;
    document.cookie = "cookieEnabled=; expires=Thu, 01 Jan 1970 00:00:00 UTC; path=/;";
    return cookiesEnabled;
  } catch (e) {
    return navigator.cookieEnabled !== false;
  }
}

